// === Tab: mySketch.js ===
// Advanced WebGL Generative Art with dat.GUI + Image Texture + Fallback
const [width, height] = [1280, 1280];

const settings = {
  speed: 0.02,
  backgroundAlpha: 0.1,
  pointSize: 2.0,
  randomX: Math.random() * 300,
  randomY: Math.random() * 300,
  baseColor: "#ffffff",
  motionMode: 0,
  saveImage: () => {
    const link = document.createElement('a');
    link.download = 'snapshot.png';
    link.href = canvas2D.toDataURL();
    link.click();
  },
  reset: () => {
    Object.assign(settings, defaultSettings);
    updateUniforms();
    gui.updateDisplay();
  },
  exportJSON: () => {
    const data = JSON.stringify(settings, null, 2);
    navigator.clipboard.writeText(data);
    alert("Settings copied to clipboard!");
  },
  importJSON: () => {
    const input = prompt("Paste JSON settings:");
    if (input) {
      try {
        Object.assign(settings, JSON.parse(input));
        updateUniforms();
        gui.updateDisplay();
      } catch (e) {
        alert("Invalid JSON");
      }
    }
  }
};

const defaultSettings = JSON.parse(JSON.stringify(settings));
let gui, canvasWebGL2, canvas2D, gl, program;
let randomVec2Loc, timeLoc, pointSizeLoc, motionModeLoc, textureLoc;
let texture, fallbackTexture;

const main = async () => {
  canvasWebGL2 = document.getElementById("canvasWebGL2");
  canvas2D = document.getElementById("canvas2D");

  gl = canvasWebGL2.getContext("webgl2");
  program = gl.createProgram();
  setShader(gl, program, vert, frag);
  gl.linkProgram(program);
  gl.useProgram(program);

  resizeCanvas(canvasWebGL2, gl, width, height);
  resizeCanvas(canvas2D, gl, width, height);

  randomVec2Loc = gl.getUniformLocation(program, "uRandomVec2");
  timeLoc = gl.getUniformLocation(program, "uTime");
  pointSizeLoc = gl.getUniformLocation(program, "uPointSize");
  motionModeLoc = gl.getUniformLocation(program, "uMotionMode");
  textureLoc = gl.getUniformLocation(program, "uTexture");

  const cols = width / 2;
  const rows = height / 2;
  const [xOff, yOff] = [2 / cols, 2 / rows];
  const [uOff, vOff] = [1 / cols, 1 / rows];

  let positionData = [], texCoordData = [];
  for (let col = 0; col < cols; col++) {
    for (let row = 0; row < rows; row++) {
      positionData.push(-1 + xOff * col + 1 / cols);
      positionData.push(1 - yOff * row - 1 / rows);
      texCoordData.push((col + 1 / cols) * uOff);
      texCoordData.push((row + 1 / rows) * vOff);
    }
  }

  setAttributeVec2(gl, program, "aPosition", positionData);
  setAttributeVec2(gl, program, "aTexCoord", texCoordData);

  setupGUI();
  try {
    await loadTexture("https://deckard.openprocessing.org/user534771/visual2681217/h583e98f440e3daa290f1a4529fda6e38/e3873fe2aa77d9b6b35169d25246b947.jpg");
  } catch (e) {
    console.warn("Image failed to load, using fallback.");
    createFallbackTexture();
  }
  animate();
};

const loadTexture = (src) => {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.src = src;
    image.onload = () => {
      texture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, image);
      gl.generateMipmap(gl.TEXTURE_2D);
      resolve();
    };
    image.onerror = reject;
  });
};

const createFallbackTexture = () => {
  const size = 2;
  var data = new Uint8Array([
    255, 0, 0, 255,
    0, 255, 0, 255,
    0, 0, 255, 255,
    255, 255, 0, 255
  ]);

  texture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, size, size, 0, gl.RGBA, gl.UNSIGNED_BYTE, data);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
};

const updateUniforms = () => {
  gl.uniform2fv(randomVec2Loc, [settings.randomX, settings.randomY]);
  gl.uniform1f(pointSizeLoc, settings.pointSize);
  gl.uniform1i(motionModeLoc, settings.motionMode);
  gl.uniform1i(textureLoc, 0);
};

let time = 0;
const animate = () => {
  gl.clearColor(0, 0, 0, settings.backgroundAlpha);
  gl.clear(gl.COLOR_BUFFER_BIT);

  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, texture);

  gl.uniform1f(timeLoc, time);
  updateUniforms();
  gl.drawArrays(gl.POINTS, 0, (width / 2) * (height / 2));
  time += settings.speed;

  drawImage(canvasWebGL2, canvas2D);
  requestAnimationFrame(animate);
};

const setupGUI = () => {
  gui = new dat.GUI();
  gui.remember(settings);

  const general = gui.addFolder("General");
  general.add(settings, "speed", 0.001, 0.1).name("Speed");
  general.add(settings, "backgroundAlpha", 0.0, 1.0).name("Background");
  general.add(settings, "pointSize", 1, 20).name("Point Size");

  const randomness = gui.addFolder("Randomness");
  randomness.add(settings, "randomX", 0, 300).onChange(updateUniforms).name("Random X");
  randomness.add(settings, "randomY", 0, 300).onChange(updateUniforms).name("Random Y");

  const visual = gui.addFolder("Visuals");
  visual.addColor(settings, "baseColor").name("Color (WIP)");
  visual.add(settings, "motionMode", { Default: 0, Spiral: 1, Pulse: 2 }).name("Motion Type");

  const actions = gui.addFolder("Actions");
  actions.add(settings, "saveImage").name("📷 Save Image");
  actions.add(settings, "reset").name("🔄 Reset Settings");
  actions.add(settings, "exportJSON").name("⬇️ Export JSON");
  actions.add(settings, "importJSON").name("⬆️ Import JSON");
};

main();

